// biome-ignore-all lint/style/useNamingConvention: an Item uses the database's column names
import { expect, test } from "bun:test";
import type { Item, Member } from "../../src/db";
import { canBorrow } from "../../src/items/borrow";

const member: Member = {
  id: "m-1",
  name: "Test",
  phone: "",
  email: "",
  joined: "2026-01-01",
  inductions: [],
};
const ladder: Item = {
  id: "ladder-01",
  name: "Step ladder",
  category: "access",
  safety_class: "A",
  deposit_cents: 1000,
  status: "in",
};

test("a free class-A tool can go out", () => {
  expect(canBorrow(member, ladder)).toEqual({ ok: true });
});

const chainsaw: Item = {
  id: "saw-01",
  name: "Chainsaw, 35 cm bar",
  category: "garden",
  safety_class: "C",
  deposit_cents: 6000,
  status: "in",
};

test("a member without the C induction cannot take a class C tool", () => {
  const decision = canBorrow(member, chainsaw);
  expect(decision.ok).toBe(false);
  if (!decision.ok) expect(decision.reason.toLowerCase()).toContain("induction");
});

test("a member with the C induction can take a free class C tool", () => {
  const inducted = { ...member, inductions: ["C"] };
  expect(canBorrow(inducted, chainsaw)).toEqual({ ok: true });
});

test("a member with only the B induction cannot take a class C tool", () => {
  const inducted = { ...member, inductions: ["B"] };
  expect(canBorrow(inducted, chainsaw).ok).toBe(false);
});

test("a class B tool needs no induction", () => {
  const drill: Item = { ...ladder, id: "drill-01", name: "Drill", safety_class: "B" };
  expect(canBorrow(member, drill)).toEqual({ ok: true });
});

test("an inducted member cannot take a class C tool that is in repair or out", () => {
  const inducted = { ...member, inductions: ["C"] };
  expect(canBorrow(inducted, { ...chainsaw, status: "repair" }).ok).toBe(false);
  expect(canBorrow(inducted, { ...chainsaw, status: "out" }).ok).toBe(false);
});

test("a tool in repair cannot go out", () => {
  expect(canBorrow(member, { ...ladder, status: "repair" }).ok).toBe(false);
});

